        optionB: { name: "Percentage-of-Revenue Budget", lowEstimate: "5%", highEstimate: "15%+", unit: "of revenue, common range depending on growth goals (illustrative)", description: "Marketing spend is set as a percentage of revenue, so it rises and falls with the firm's actual financial performance.", pros: ["Naturally scales with the firm's financial capacity", "Reduces risk of overspending during a slow period"], cons: ["Can create a downward spiral — less revenue means less marketing, which can mean even less revenue", "Revenue can lag marketing results by months, so the two don't always move in sync"] },
