export const costEstimator: CostIndustrySection[] = [
  {
    industrySlug: "home-services",
    categories: homeServicesCategories,
  },
  {
    industrySlug: "legal",
    categories: legalCategories,
  },
  {
    industrySlug: "financial-services",
    categories: financialServicesCategories,
  },
  {
    industrySlug: "insurance",
    categories: insuranceCategories,
  },
  {
    industrySlug: "real-estate",
    categories: realEstateCategories,
  },
  {
    industrySlug: "education",
    categories: educationCategories,
  },
];

export function getCostIndustry(industrySlug: string) {
  return costEstimator.find((c) => c.industrySlug === industrySlug);
}

export function getCostCategory(industrySlug: string, categorySlug: string) {
  const section = getCostIndustry(industrySlug);
  return section?.categories.find((c) => c.slug === categorySlug);
}

export function getCostArticle(industrySlug: string, categorySlug: string, articleSlug: string) {
  const category = getCostCategory(industrySlug, categorySlug);
  return category?.articles.find((a) => a.slug === articleSlug);
}
